def sha(data):
    return hashlib.sha256(data).hexdigest()

def fenster(jetzt):
    jetzt = jetzt.astimezone(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin %s Minute %02d" % (jetzt.strftime("%H:%M"), jetzt.minute)

def laden():
    return json.loads(PAYLOAD_TEXT)

def tausch(data, old, new):
    if isinstance(data, str):
        old, new = old.decode() if isinstance(old, bytes) else old, new.decode() if isinstance(new, bytes) else new
        if new in data:
            return data
        if data.count(old) != 1:
            raise RuntimeError("stelle")
        return data.replace(old, new, 1)
    if new in data:
        return data
    if data.count(old) != 1:
        raise RuntimeError("stelle")
    return data.replace(old, new, 1)

def soll_setzen(text):
    for name, wert in SOLL.items():
        muster = r"(\$\{%s:-)[^}\n]+" % name
        if re.search(muster, text):
            text, n = re.subn(muster, r"\g<1>" + wert, text, count=1)
            if n != 1 or len(re.findall(muster, text)) != 1:
                raise RuntimeError(name)
            continue
        if name == "FC_PUSH_BYTES" and "${FC_PUSH_SHA16:-" in text:
            text = text.replace(
                "${FC_PUSH_SHA16:-%s}" % SOLL["FC_PUSH_SHA16"],
                "${FC_PUSH_SHA16:-%s}\"\nPUSH_BYTES=\"${FC_PUSH_BYTES:-%s}" % (SOLL["FC_PUSH_SHA16"], wert),
                1,
            )
            continue
        raise RuntimeError(name)
    return text

def _null_zeile(zeile):
    if "$(" not in zeile or "tr -d" in zeile:
        return zeile, False
    fund = re.search(r"\$\((.*)\)", zeile)
    if not fund:
        return zeile, False
    return zeile[:fund.start()] + "$( { %s; } | tr -d '\\0' )" % fund.group(1) + zeile[fund.end():], True


def null_frei(text):
    """Nullbytes aus device-tree-Lesen und aus Zeile 318 (bash: ignored null byte)."""
    zeilen, zahl = [], 0
    roh = text.splitlines(keepends=True)
    for nummer, zeile in enumerate(roh, start=1):
        if "/proc/device-tree" in zeile or nummer == 318:
            zeile, getroffen = _null_zeile(zeile)
            zahl += int(getroffen)
        zeilen.append(zeile)
    if zahl < 1:
        raise RuntimeError("null")
    return "".join(zeilen)

def fullcheck_neu(text):
    if "elDBYTES" in text:
        raise RuntimeError("elif")
    if text.count('FC_VERSION="2.5"') != 1 and 'FC_VERSION="2.6"' not in text:
        raise RuntimeError("version")
    if 'FC_VERSION="2.6"' in text and "flugfunk-7: Mount" in text and "tr -d" in text:
        return text
    if 'FC_VERSION="2.5"' not in text:
        raise RuntimeError("version")
    neu = text.replace('FC_VERSION="2.5"', 'FC_VERSION="2.6"', 1)
    neu = soll_setzen(neu)
    neu = null_frei(neu)
    gelb = '    gelb) warn "Stick" "$TXT" "Watchdog" ;;\n'
    if neu.count(gelb) == 1 and 'info) info "Stick"' not in neu:
        neu = neu.replace(gelb, '    info) info "Stick" "$TXT" "Empfang" ;;\n' + gelb, 1)
    metar = 'else warn "METAR EDDN" "nicht aktuell" "Cache 10 min, aviationweather."; fi'
    if neu.count(metar) == 1:
        neu = neu.replace(metar, 'elif [[ "$HTTP_BODY" == *\'"metar_aktuell": true\'* || "$HTTP_BODY" == *\'"metar_aktuell":true\'* ]]; then ok "METAR EDDN" "aktuell"; else warn "METAR EDDN" "nicht aktuell" "aviationweather oder NOAA, Cache 10 min."; fi', 1)
    anker = "  # --- SDR-Watchdog (Datenlage der Sticks, nur lesen)\n"
    if neu.count(anker) != 1:
        raise RuntimeError("anker")
    if "flugfunk-7: Mount" not in neu:
        neu = neu.replace(anker, BLOCK + anker, 1)
    if "# fullcheck.sh Basis sdr-stabil" in neu:
        neu = neu.replace("# fullcheck.sh Basis sdr-stabil", "# fullcheck.sh Basis flugfunk-7", 1)
    elif "Basis flugfunk-7" not in neu and "# fullcheck.sh" in neu:
        neu = neu.replace("# fullcheck.sh", "# fullcheck.sh Basis flugfunk-7", 1)
    if "elDBYTES" in neu:
        raise RuntimeError("elif")
    return neu

def bash_n(text):
    tmp = Path(tempfile.mkstemp(prefix="fullcheck-", suffix=".sh")[1])
    try:
        tmp.write_text(text)
        r = subprocess.run(["bash", "-n", str(tmp)], capture_output=True, text=True)
        return r.returncode == 0, (r.stderr or "").strip()
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass

