def selftest():
    assert FC_FEST == "c04bbdc1941ca7c766e548bc99852410f4bd02f0b136869d2988297fc0b0ca4a" and FC_BYTES == 97067
    roh = laden()
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk7-"))
    try:
        sdr = b""
        for paar in roh["sdr"]:
            sdr += base64.b64decode(paar["old"]) + b"\n"
        (ordner / "prepper_sdr.py").write_bytes(sdr)
        dash = b""
        for paar in roh["dash"]:
            dash += base64.b64decode(paar["old"]) + b"\n"
        (ordner / "dashboard.py").write_bytes(dash)
        (ordner / "flugfunk.py").write_bytes(b"x" * 10)
        fp = ordner / "fullcheck.sh"
        fp.write_text(FIX)
        vorher = fp.read_bytes()
        assert apply_dir(ordner, True, True, hashcheck=False, fullcheck_hash=sha(vorher), full_pfad=fp) == 0
        assert fp.read_bytes() == vorher
        von = datetime(2026, 11, 26, 19, 4, tzinfo=ZoneInfo("Europe/Berlin"))
        assert apply_dir(ordner, False, False, jetzt=von, hashcheck=False, fullcheck_hash=sha(vorher), full_pfad=fp) == 2
        assert fp.read_bytes() == vorher and not (ordner / "icecast-flugfunk.pw").exists()
        innen = datetime(2026, 11, 26, 19, 10, tzinfo=ZoneInfo("Europe/Berlin"))
        protokoll = tempfile.NamedTemporaryFile("w+", delete=False)
        try:
            alt = sys.stdout
            sys.stdout = protokoll
            rc = apply_dir(ordner, False, True, jetzt=innen, hashcheck=False, fullcheck_hash=sha(vorher), full_pfad=fp)
            sys.stdout = alt
            protokoll.flush()
            text = Path(protokoll.name).read_text()
        finally:
            sys.stdout = alt
            try:
                os.unlink(protokoll.name)
            except OSError:
                pass
        assert rc == 0
        neu = fp.read_text()
        assert 'FC_VERSION="2.6"' in neu and "elDBYTES" not in neu and "tr -d" in neu
        assert "57df9398bd5813bc" in neu and "1390064" in neu and "12237" in neu
        assert "info) info" in neu and "flugfunk-7: Mount" in neu and "Wetterfelder" in neu and "Kanalzaehler" in neu
        assert bash_n(neu)[0]
        assert b"FF7_WELLE_PROZENT" in (ordner / "prepper_sdr.py").read_bytes()
        assert b"_ff_mount" in (ordner / "dashboard.py").read_bytes()
        ff = ordner / "flugfunk-neu.py"
        ff.write_bytes(base64.b64decode(roh["flugfunk"]))
        compile(ff.read_bytes(), "flugfunk.py", "exec")
        pw = (ordner / "icecast-flugfunk.pw").read_text().strip()
        assert pw and pw not in text and "icecast://" not in text
        assert oct((ordner / "icecast-flugfunk.pw").stat().st_mode & 0o777) == "0o600"
    finally:
        shutil.rmtree(ordner, ignore_errors=True)
    return "flugfunk-7 ok"

